overlay.scripts/lab/sample-report.mjs:
// Formats a run record's KPI block as aligned text lines.
export function kpiLines(record) {
  const entries = Object.entries(record.kpis ?? {});
  const width = Math.max(0, ...entries.map(([id]) => id.length));
  return entries.map(([id, measure]) => `${id.padEnd(width)}  ${measure.value ?? "none"} n=${measure.n}`);
}

