import test from "node:test";
import assert from "node:assert/strict";

const LAB_FILES = [
  "scripts/lab/gate.mjs",
  "scripts/lab/record.mjs",
  "scripts/lab/sample-report.mjs",
  "scripts/lab/stats.mjs",
];

test("every lab script lives under scripts/lab and ends in .mjs", () => {
  for (const file of LAB_FILES) {
    assert.match(file, /^scripts\/lab\/[a-z-]+\.mjs$/);
  }
});

